import type { Lesson, Level, Question } from './types.ts';

export type Track = 'software' | 'business' | 'humanities' | 'health';
export interface Criterion { label: string; pattern: RegExp }
export interface QuestionSpec { question: Question; track: Track | 'all'; criteria: Criterion[]; example: string }

export function trackForMajor(major: string): Track {
  const value = major.toLowerCase();
  if (/health|nurs|medic|biolog|pharma|public health|psycholog/.test(value)) return 'health';
  if (/business|econom|financ|account|market|management|commerce/.test(value)) return 'business';
  if (/english|history|human|arts|politic|law|communication|education|sociolog|philosoph/.test(value)) return 'humanities';
  return 'software';
}

const criterion = (label: string, pattern: RegExp): Criterion => ({ label, pattern });
const specs: QuestionSpec[] = [];
function technical(track: Track, id: string, difficulty: Level, topic: string, title: string, prompt: string, criteria: Criterion[], example: string, starter?: string): void {
  specs.push({ track, question: { id, kind: 'technical', topic, difficulty, title, prompt, starter, hints: criteria.map(item => item.label) }, criteria, example });
}

technical('software', 'sw-positive-sum', 'beginner', 'Arrays', 'Sum the useful values',
  'Write JavaScript function sumPositive(values) that returns the sum of numbers greater than zero. For [3, -2, 0, 5] it must return 8, and for [] it must return 0. Include your code, why zero is excluded, and time complexity. Code is reviewed, never executed on the server.',
  [criterion('Filter values strictly greater than zero.', /(?:\b\w+\s*>\s*0|0\s*<\s*\w+)/), criterion('Accumulate and return a numeric sum, including an initial zero.', /(?:return|=>)[\s\S]*(?:reduce|sum|total)|(?:sum|total)[\s\S]*return/), criterion('Explain linear time and the empty-array result.', /(?:O\(n\)|linear)[\s\S]*(?:empty|\[\])|(?:empty|\[\])[\s\S]*(?:O\(n\)|linear)/)],
  'function sumPositive(values) { let total = 0; for (const value of values) { if (value > 0) total += value; } return total; } Zero is excluded because it is not greater than zero. The initial total makes an empty array return 0. Each value is visited once, so time is O(n), and extra space is O(1).',
  'function sumPositive(values) {\n  // Return the sum of positive values.\n}\n\n// Explain your approach and complexity.');
technical('software', 'sw-unique', 'beginner', 'Arrays', 'Keep first occurrences',
  'Write JavaScript function unique(values) that removes duplicate strings while preserving their first occurrence. Explain the result for ["a", "b", "a"], the empty input, and complexity.',
  [criterion('Track previously seen values with a set or membership check.', /\bSet\b|\.has\(|\.includes\(/), criterion('Preserve order and return the result.', /return[\s\S]*(?:result|output|\[\.\.\.|Array\.from)|(?:result|output)\.push\(/), criterion('Explain the expected a,b result and empty input.', /(?:a[^\n]{0,15}b)[\s\S]*(?:empty|\[\])|(?:empty|\[\])[\s\S]*a[^\n]{0,15}b/)],
  'function unique(values) { return [...new Set(values)]; } A Set stores values in insertion order and accepts each string only once, so the example returns ["a", "b"]. Empty input returns an empty array. Average time is O(n) and space is O(n) for the distinct values.',
  'function unique(values) {\n  // Keep each string once, in its original order.\n}');
technical('software', 'sw-debug', 'beginner', 'Debugging', 'Find the missing last item',
  'A loop reads values[i] with i <= values.length. Describe the bug, give the corrected loop condition, and explain tests for an empty array and a one-element array.',
  [criterion('Identify the out-of-bounds or undefined access.', /out.of.bounds|undefined|beyond|past.*last/i), criterion('Use i < values.length.', /i\s*<\s*values\.length/), criterion('Explain empty and one-element tests.', /empty[\s\S]*(?:one|single|1)|(?:one|single|1)[\s\S]*empty/i)],
  'Array indices stop at length minus one. Using <= accesses values[length], which is undefined and out of bounds. The corrected condition is i < values.length. An empty array should execute no iterations. A one-element array should read index zero once and never index one. Those tests catch both boundary cases.');
technical('software', 'sw-api', 'beginner', 'APIs', 'Handle a failed request',
  'An app fetches a profile. The server returns 401, sometimes 500, and sometimes a network timeout. Describe the user experience and recovery for all three, including what must never be logged.',
  [criterion('Use sign-in recovery for 401.', /401[\s\S]*(?:sign.in|log.in|auth)|(?:sign.in|log.in|auth)[\s\S]*401/i), criterion('Bound retries or offer retry for server and network errors.', /(?:retry|backoff)[\s\S]*(?:500|timeout)|(?:500|timeout)[\s\S]*(?:retry|backoff)/i), criterion('Keep tokens and personal data out of logs.', /(?:never|avoid|redact|not)[\s\S]*(?:token|password|personal)/i)],
  'A 401 means the session may have expired, so offer sign-in and preserve the current task. A 500 should show a recoverable error with a retry button. A timeout can retry with bounded exponential backoff, then show an offline message. Never log passwords, bearer tokens, or personal profile data; log a request ID and status instead.');
technical('software', 'sw-count-even', 'beginner', 'Arrays', 'Count the even numbers',
  'Write JavaScript function countEven(values) that returns how many integers in the array are even. For [1, 2, 4, 7] it must return 2, and for [] it must return 0. Include your code, how it treats negative numbers, and time complexity. Code is reviewed, never executed on the server.',
  [criterion('Test evenness with a remainder of zero after dividing by two.', /%\s*2\s*(?:===?|==)\s*0|\b0\s*(?:===?|==)\s*\w+\s*%\s*2/), criterion('Count the matching values and return the count, starting from zero.', /(?:return|=>)[\s\S]*(?:count|total|length)|(?:count|total)[\s\S]*return/), criterion('Explain linear time and the empty-array result.', /(?:O\(n\)|linear)[\s\S]*(?:empty|\[\])|(?:empty|\[\])[\s\S]*(?:O\(n\)|linear)/)],
  'function countEven(values) { let count = 0; for (const value of values) { if (value % 2 === 0) count += 1; } return count; } A value is even when dividing by two leaves a remainder of zero, which also holds for negative numbers such as -4. The initial count makes an empty array return 0. Each value is visited once, so time is O(n), and extra space is O(1).',
  'function countEven(values) {\n  // Return how many values are even.\n}\n\n// Explain your approach and complexity.');
technical('software', 'sw-frequency', 'intermediate', 'Data structures', 'Count words efficiently',
  'Design a word-frequency function for text. Explain case normalization, punctuation, the counting data structure, complexity, and how you test empty input and repeated words.',
  [criterion('Normalize case and punctuation.', /lowercase|toLowerCase|case.insensitive/i), criterion('Use a map or dictionary of counts.', /(?:map|dictionary|object)[\s\S]*(?:count|increment)|(?:count|increment)[\s\S]*(?:map|dictionary|object)/i), criterion('Explain time complexity and a boundary test.', /(?:O\(n\)|linear)[\s\S]*(?:empty|repeat)|(?:empty|repeat)[\s\S]*(?:O\(n\)|linear)/i)],
  'Normalize text to lowercase and tokenize word characters so punctuation is excluded. A Map from each word to its count increments on every token. For n characters and tokens the traversal is linear, O(n), with space for distinct words. Test empty input, punctuation-only input, and "Cat cat!" producing cat with count two.');
technical('software', 'sw-search', 'intermediate', 'Algorithms', 'Search a sorted list',
  'Explain binary search for a sorted array, including updates to both bounds, how the loop terminates, the not-found value, and complexity. You may include JavaScript.',
  [criterion('Maintain low/high bounds and a midpoint.', /(?:low|left)[\s\S]*(?:high|right)[\s\S]*(?:mid|middle)/i), criterion('Advance beyond the midpoint, avoiding an infinite loop.', /mid\s*\+\s*1|midpoint.*plus one|middle.*plus one/i), criterion('Explain logarithmic time and not found.', /(?:O\(log\s*n\)|logarithmic)[\s\S]*(?:-1|not.found)|(?:-1|not.found)[\s\S]*(?:O\(log\s*n\)|logarithmic)/i)],
  'Set low to zero and high to the last index. Compare the middle value with the target. If smaller, set low = mid + 1; if larger, set high = mid - 1; otherwise return mid. Each step removes the midpoint and halves the range. When low exceeds high return -1 for not found. Time is O(log n) and extra space is O(1).');
technical('software', 'sw-cache', 'intermediate', 'Systems', 'Cache without stale surprises',
  'A dashboard caches user profiles for five minutes. Design cache keys, expiry and invalidation after a profile edit. Explain one privacy risk and one test.',
  [criterion('Scope cache keys by authenticated user.', /(?:user|account)[\s\S]*(?:key|scope)|(?:key|scope)[\s\S]*(?:user|account)/i), criterion('Expire entries and invalidate after writes.', /(?:expir|ttl)[\s\S]*(?:invalidat|edit|write)|(?:invalidat|edit|write)[\s\S]*(?:expir|ttl)/i), criterion('Describe isolation and a test.', /(?:test|verify)[\s\S]*(?:another|different|two|isolation)|(?:another|different|two|isolation)[\s\S]*(?:test|verify)/i)],
  'Cache keys must contain the authenticated user ID and resource version. Entries expire after a five-minute TTL, and a successful profile edit invalidates that user entry immediately. Sharing a key across accounts could expose another person\'s profile. Test two accounts with distinct profiles, a write followed by a read, and expiry using a controllable clock.');
technical('software', 'sw-sql', 'intermediate', 'Databases', 'Make a query safe',
  'A login query concatenates email into SQL. Explain how to prevent injection, store passwords, and test an input containing a quote without exposing user data.',
  [criterion('Bind parameters instead of concatenating SQL.', /bound|bind|parameterized|prepared/i), criterion('Use a salted password hash.', /(?:salt|scrypt|argon2|bcrypt)[\s\S]*(?:hash|password)|(?:hash|password)[\s\S]*(?:salt|scrypt|argon2|bcrypt)/i), criterion('Test quote or injection input without leaks.', /(?:quote|injection|\')[\s\S]*(?:test|no|not|never)|(?:test|no|not|never)[\s\S]*(?:quote|injection)/i)],
  'Use a prepared statement with bound parameters for email so the database treats it as data. Store a unique salt and a slow password hash such as scrypt, never plaintext passwords. Test an email containing a quote and an injection-like string; neither should change query structure or reveal another account. Keep errors generic and exclude secrets from logs.');
technical('software', 'sw-running-total', 'intermediate', 'Arrays', 'Build running totals',
  'Write JavaScript function runningTotals(values) that returns a new array where each item is the sum of all values up to and including that position. For [1, 2, 3] it must return [1, 3, 6], and for [] it must return []. Include your code, whether the input array changes, and time and space complexity. Code is reviewed, never executed on the server.',
  [criterion('Carry a running sum from one position to the next.', /(?:sum|total|running|acc)\w*\s*(?:\+=|=\s*\w+\s*\+)|reduce|\+=/i), criterion('Build and return a new array of the totals.', /(?:push|map|\[\.\.\.)[\s\S]*return|return[\s\S]*(?:totals|result|map)/), criterion('Explain that the input is not changed, plus linear time and space.', /(?:unchanged|not (?:changed|modified|mutated)|without (?:changing|mutating))[\s\S]*(?:O\(n\)|linear)|(?:O\(n\)|linear)[\s\S]*(?:unchanged|not (?:changed|modified|mutated)|without (?:changing|mutating))/i)],
  'function runningTotals(values) { const totals = []; let sum = 0; for (const value of values) { sum += value; totals.push(sum); } return totals; } The input array is not changed because every result goes into a new array. An empty input returns an empty array. Each value is visited once, so time is O(n), and the output needs O(n) extra space.',
  'function runningTotals(values) {\n  // Return the running sums as a new array.\n}\n\n// Explain whether the input changes, and the complexity.');
technical('software', 'sw-concurrency', 'advanced', 'Concurrency', 'Prevent a double reward',
  'Two retries submit the same completed interview answer at once. Design an idempotency rule and atomic database update that grants only one reward. Explain an observable test.',
  [criterion('Use a unique answer or request identifier.', /unique|idempotenc/i), criterion('Validate and write atomically with a transaction or conditional update.', /transaction|compare.and.swap|conditional.update|version.check/i), criterion('Test concurrent submissions and one reward.', /(?:concurrent|parallel|simultaneous)[\s\S]*(?:one|single|once)|(?:one|single|once)[\s\S]*(?:concurrent|parallel|simultaneous)/i)],
  'Use a unique key consisting of session ID and question ID for each submitted answer. In one transaction, verify the active question and version, insert the attempt, and conditionally mark the session complete. A duplicate returns its stored result. Submit two concurrent requests in a test and verify one attempt, one completed session, and one reward deadline.');
technical('software', 'sw-pagination', 'advanced', 'APIs', 'Page changing data',
  'Design pagination for a feed receiving new items while a user scrolls. Compare offset and cursor pagination, specify a stable sort, and address duplicate and deleted items.',
  [criterion('Compare cursor stability with shifting offsets.', /cursor[\s\S]*offset|offset[\s\S]*cursor/i), criterion('Use a stable timestamp and ID sort.', /(?:timestamp|createdAt|time)[\s\S]*(?:id|identifier)|(?:id|identifier)[\s\S]*(?:timestamp|createdAt|time)/i), criterion('Deduplicate and handle deletion.', /(?:dedup|duplicate)[\s\S]*(?:delet|missing)|(?:delet|missing)[\s\S]*(?:dedup|duplicate)/i)],
  'Offset pagination shifts when new rows arrive, causing skips or duplicates. Use a cursor containing the last timestamp and ID, ordered by both fields for a stable tie-breaker. Fetch rows older than that pair. The client deduplicates by ID. A deleted cursor row still works because its sort values are in the cursor; missing items are omitted.');
technical('software', 'sw-tests', 'advanced', 'Testing', 'Test a payment boundary',
  'A purchase service calls an external provider and saves a receipt. Design tests for timeout, success, and duplicate retry without real charges. Explain the invariant that matters most.',
  [criterion('Use a fake provider without live charges.', /mock|fake|stub/i), criterion('Test timeout and retry or duplication.', /timeout[\s\S]*(?:retry|duplicate)|(?:retry|duplicate)[\s\S]*timeout/i), criterion('Assert exactly one charge or receipt.', /(?:one|single|exactly|once)[\s\S]*(?:charge|receipt)|(?:charge|receipt)[\s\S]*(?:one|single|exactly|once)/i)],
  'Inject a fake provider and a temporary database so no live charges occur. Test success, timeout before confirmation, and duplicate retry with the same idempotency key. The key invariant is exactly one charge and one receipt for one purchase. Assert stored state and provider call identity, and verify failed attempts do not mark the purchase paid.');
technical('software', 'sw-privacy', 'advanced', 'Security', 'Protect a mobile session',
  'Design authentication for a mobile app calling a backend. Cover token storage, expiration, server-side authorization, and what changes for a public production deployment.',
  [criterion('Store credentials in secure storage.', /secure.storage|keychain|keystore/i), criterion('Authorize each resource and expire tokens.', /(?:authoriz|ownership)[\s\S]*(?:expir|revok)|(?:expir|revok)[\s\S]*(?:authoriz|ownership)/i), criterion('Require HTTPS for production.', /HTTPS|TLS/)],
  'Store the bearer token in platform secure storage rather than plain preferences. Tokens expire and can be revoked. Every backend resource checks authenticated ownership; a client-supplied user ID is never authority. A public production deployment needs HTTPS with certificate validation, rate limits, secret management, and minimal sensitive logs. LAN HTTP is limited to local testing.');
technical('software', 'sw-max-subarray', 'advanced', 'Algorithms', 'Find the best run',
  'Write JavaScript function maxSubarraySum(values) that returns the largest sum of any run of adjacent numbers. For [2, -5, 3, 4] it must return 7, for [-3, -1, -2] it must return -1 because a run needs at least one number, and for [] it must return 0. Explain how one pass decides whether to extend the current run or start over, and give time and space complexity. Code is reviewed, never executed on the server.',
  [criterion('Track the best run ending at the current number and the best sum seen so far.', /(?:current|run)\w*[\s\S]*(?:best|max)|(?:best|max)\w*[\s\S]*(?:current|run)/i), criterion('Choose between extending the run and starting over, then return the best sum.', /(?:Math\.max|extend|start(?:s|ing)? (?:over|again|fresh|a new))[\s\S]*return|return[\s\S]*(?:Math\.max|extend|start(?:s|ing)? (?:over|again|fresh|a new))/i), criterion('Handle empty and all-negative input, and state linear time with constant space.', /^(?=[\s\S]*(?:empty|\[\]))(?=[\s\S]*negative)(?=[\s\S]*(?:O\(n\)|linear))/i)],
  'function maxSubarraySum(values) { if (values.length === 0) return 0; let best = values[0]; let current = values[0]; for (let index = 1; index < values.length; index++) { current = Math.max(values[index], current + values[index]); best = Math.max(best, current); } return best; } At each number the current run either extends the previous run or starts over at that number, whichever is larger, so an all-negative array returns its largest single number, such as -1 for [-3, -1, -2]. An empty array returns 0 by definition. One pass makes time O(n) and extra space O(1), and best records the highest sum seen at any position.',
  'function maxSubarraySum(values) {\n  // Return the largest sum of any run of adjacent values.\n}\n\n// Explain your approach, the empty case and complexity.');
technical('software', 'sw-distributed', 'expert', 'Distributed systems', 'Deliver events once in effect',
  'Design an interview reward service with at-least-once event delivery. Explain the transaction/outbox boundary, consumer idempotency, crash recovery, and the consistency tradeoff.',
  [criterion('Commit domain state and an outbox record together.', /outbox[\s\S]*transaction|transaction[\s\S]*outbox/i), criterion('Deduplicate consumer processing with a unique key.', /(?:idempot|dedup)[\s\S]*(?:key|id|unique)|(?:key|id|unique)[\s\S]*(?:idempot|dedup)/i), criterion('Explain crashes and eventual consistency.', /(?:crash|recover|retry)[\s\S]*eventual|eventual[\s\S]*(?:crash|recover|retry)/i)],
  'Write the completed interview and an outbox event in the same database transaction. A relay publishes unacknowledged events and retries after crashes. The consumer uses a unique event ID in a transaction to deduplicate reward updates. Crashing after publish can cause delivery again, but the effect stays once. Rewards become eventually consistent; monitoring lag and retry failures makes that tradeoff visible.');
technical('software', 'sw-design', 'expert', 'System design', 'Scale a rate limiter',
  'Design a rate limiter across several API servers. Describe the key, atomic shared operation, time/window choice, behavior if storage fails, and how you measure fairness.',
  [criterion('Use shared atomic storage keyed by user or client.', /(?:atomic|transaction)[\s\S]*(?:shared|redis|store)|(?:shared|redis|store)[\s\S]*(?:atomic|transaction)/i), criterion('Compare token buckets or sliding windows.', /token.bucket|sliding.window/i), criterion('Explain fail-open/closed tradeoffs and metrics.', /(?:fail.open|fail.closed)[\s\S]*(?:metric|fair|reject)|(?:metric|fair|reject)[\s\S]*(?:fail.open|fail.closed)/i)],
  'Key limits by authenticated user with a bounded fallback client key. Use shared storage and an atomic script to refill and spend a token bucket. Token buckets allow controlled bursts; sliding windows provide stricter rolling limits. If storage fails, choose fail-closed for expensive AI operations and a documented fail-open policy for low-risk reads. Measure rejection rate, fairness by account, storage latency, and limit accuracy across servers.');
technical('software', 'sw-consistency', 'expert', 'Databases', 'Move money safely',
  'Describe a transfer between two accounts. Explain validation, transactional isolation, overdraft prevention under concurrent transfers, idempotency, and reconciliation.',
  [criterion('Apply debit and credit in one transaction.', /transaction[\s\S]*(?:debit|credit)|(?:debit|credit)[\s\S]*transaction/i), criterion('Lock or conditionally update balances against concurrent overdraft.', /lock|serializable|conditional|compare.and.swap/i), criterion('Use idempotency and reconciliation.', /idempot[\s\S]*reconcil|reconcil[\s\S]*idempot/i)],
  'Validate amount and account ownership, then debit and credit within one transaction. Lock account rows in a consistent order or use serializable isolation with retries, and condition the debit on sufficient balance to prevent concurrent overdrafts. A unique transfer ID makes retries idempotent. Keep an append-only ledger and reconcile ledger sums against balances to detect inconsistencies.');
technical('software', 'sw-observability', 'expert', 'Reliability', 'Investigate a latency incident',
  'P95 API latency doubles after a deploy while average CPU stays low. Give a hypothesis-driven investigation covering traces, queueing, database changes, rollback, and confirmation.',
  [criterion('Inspect traces and tail latency by endpoint.', /trace[\s\S]*(?:p95|tail|endpoint)|(?:p95|tail|endpoint)[\s\S]*trace/i), criterion('Check queues, locks or query plans.', /queue|lock|query.plan|connection.pool/i), criterion('Define rollback and verify recovery.', /rollback[\s\S]*(?:verify|confirm|metric)|(?:verify|confirm|metric)[\s\S]*rollback/i)],
  'Segment P95 and error rate by endpoint and compare traces before and after deployment. Low CPU suggests waiting: inspect connection-pool queues, database locks, slow query plans, and downstream spans. Correlate the changed query or dependency with affected requests. Rollback if an agreed latency/error threshold is breached. Confirm recovery using tail-latency metrics and a controlled replay, then test the hypothesis before redeploying.');
technical('software', 'sw-memoize', 'expert', 'Systems', 'Memoize without surprises',
  'Write JavaScript function memoize(compute) that returns a function which calls compute(key) once per distinct key and returns the saved result on later calls, including when the saved result is undefined, 0 or false. Explain why you check for a key instead of testing the saved value, and what happens to memory when keys never repeat. Code is reviewed, never executed on the server.',
  [criterion('Store results in a Map keyed by the argument.', /\bnew Map\b|\bMap\(\)/), criterion('Check with has before reading, compute once on a miss, then save and return the value.', /\.has\([\s\S]*\.set\([\s\S]*return/), criterion('Explain why has is used instead of a falsy check, and the unbounded memory growth.', /^(?=[\s\S]*(?:falsy|undefined|\b0\b|false))(?=[\s\S]*(?:grow|unbounded|evict|memory))/i)],
  'function memoize(compute) { const cache = new Map(); return function (key) { if (cache.has(key)) return cache.get(key); const value = compute(key); cache.set(key, value); return value; }; } The has check decides whether a result exists, so a saved undefined, 0 or false is returned instead of being computed again, which a falsy test on the value would get wrong. The cache never forgets, so memory grows without bound when keys never repeat; a size limit with eviction would bound it.',
  'function memoize(compute) {\n  // Return a function that caches compute(key) results.\n}\n\n// Explain the cache check and the memory tradeoff.');

type Scenario = [string, Level, string, string, string, Criterion[], string];
const business: Scenario[] = [
  ['margin', 'beginner', 'Financial reasoning', 'Revenue is not profit', 'A shop sells 100 items at $20 each. Each costs $12; monthly fixed costs are $500. Calculate revenue, contribution margin and operating profit, then explain why revenue alone is misleading.', [criterion('Calculate revenue of $2,000.', /2[,.]?000/), criterion('Calculate contribution of $800 and profit of $300.', /800[\s\S]*300|300[\s\S]*800/), criterion('Distinguish fixed and variable costs.', /fixed[\s\S]*variable|variable[\s\S]*fixed/i)], 'Revenue is 100 times $20, or $2,000. Variable cost is $1,200, leaving $800 in contribution margin. Subtract the $500 fixed cost to get $300 operating profit. Revenue alone ignores costs and cannot show profitability. The contribution per item is $8, which helps evaluate another sale.'],
  ['conversion', 'beginner', 'Analytics', 'Read a funnel', '1,000 visitors produce 80 signups and 20 purchases. Calculate signup and signup-to-purchase conversion. Identify one improvement hypothesis and how you would test it.', [criterion('Calculate 8% signups and 25% purchases among signups.', /8\s*%[\s\S]*25\s*%|25\s*%[\s\S]*8\s*%/), criterion('Propose a measurable hypothesis.', /hypothes|because|predict/i), criterion('Use a controlled comparison or A/B test.', /A\/B|control|random/i)], 'Signup conversion is 80 divided by 1,000, or 8%. Signup-to-purchase conversion is 20 divided by 80, or 25%. My hypothesis is that clearer onboarding improves purchase conversion because new users better understand value. Run a randomized A/B test with a control and compare conversion, sample size and refund rate.'],
  ['priority', 'beginner', 'Decision making', 'Choose a project', 'Two projects cost the same. A is expected to save 200 staff hours with high confidence; B may save 400 hours with a 25% success chance. Compare expected benefit and state a decision plus one assumption to validate.', [criterion('Compute B expected benefit of 100 hours.', /100/), criterion('Choose A based on risk-adjusted benefit.', /(?:choose|prefer|recommend|select)[\s\S]*\bA\b/i), criterion('Identify an assumption or uncertainty.', /assum|uncertain|validate/i)], 'Project B has an expected benefit of 400 times 25%, or 100 hours. I recommend A because its 200 hours of high-confidence savings exceed B\'s risk-adjusted benefit. I assume the cost and value of an hour are comparable and that success is measurable. Validate the confidence estimate with a small pilot before committing.'],
  ['break-even', 'beginner', 'Financial reasoning', 'Find break-even', 'A service charges $50 per customer and has $20 variable cost per customer plus $900 fixed cost. Calculate break-even customers and explain a risk if acquisition costs were omitted.', [criterion('Calculate $30 contribution and 30 customers.', /30/), criterion('Explain fixed cost divided by contribution.', /900[\s\S]*30|fixed[\s\S]*(?:divid|contribution)/i), criterion('Account for acquisition cost risk.', /acquisition[\s\S]*(?:cost|risk|profit)|(?:cost|risk|profit)[\s\S]*acquisition/i)], 'Each customer contributes $50 minus $20, or $30 toward fixed costs. Break-even is $900 divided by $30, which is 30 customers. At that volume operating profit is zero. If acquisition cost is omitted, the contribution is overstated and actual break-even is higher. I would include incremental marketing cost and test retention before forecasting profits.'],
  ['experiment', 'intermediate', 'Experiment design', 'Measure a pricing change', 'Design an experiment for a 10% price increase. Define randomization, primary metric, guardrails, duration and a condition for stopping early.', [criterion('Randomize comparable customers with a control.', /random[\s\S]*control|control[\s\S]*random/i), criterion('Measure revenue or profit and retention.', /(?:revenue|profit)[\s\S]*(?:retention|churn)|(?:retention|churn)[\s\S]*(?:revenue|profit)/i), criterion('Specify duration and an early-stop guardrail.', /(?:week|duration|sample)[\s\S]*(?:stop|guardrail)|(?:stop|guardrail)[\s\S]*(?:week|duration|sample)/i)], 'Randomize comparable customers between current-price control and the 10% increase. Primary metric is profit per eligible visitor, with retention, complaints and refunds as guardrails. Predefine sample size and run across complete weekly cycles. Stop early only for a material guardrail breach, not a promising intermediate result, and check confidence intervals before deciding.'],
  ['cohort', 'intermediate', 'Analytics', 'Explain a retention drop', 'Overall retention falls while every acquisition-channel cohort stays stable. Explain a plausible cause, analysis needed, and one reason not to change the product immediately.', [criterion('Recognize a changing channel mix.', /mix|Simpson/i), criterion('Compare cohorts or weighting.', /cohort[\s\S]*(?:weight|channel|compare)|(?:weight|channel|compare)[\s\S]*cohort/i), criterion('Avoid a causal conclusion without evidence.', /(?:caus|evidence)[\s\S]*(?:not|avoid|before)|(?:not|avoid|before)[\s\S]*(?:caus|evidence)/i)], 'A changing acquisition mix can lower overall retention even if channel cohorts remain stable. Compare cohort sizes and calculate retention with fixed channel weights to separate composition from within-channel changes. Check time windows and tracking quality. This observation is not evidence of a product-caused decline, so avoid immediate product changes before testing the acquisition-mix explanation.'],
  ['forecast', 'intermediate', 'Forecasting', 'Forecast responsibly', 'Forecast sales with one year of monthly data and strong seasonality. Describe a baseline, validation method, uncertainty, and a risk of overfitting.', [criterion('Use a seasonal or simple baseline.', /seasonal|baseline/i), criterion('Validate forward in time, not random leakage.', /(?:holdout|backtest|forward|time.split)/i), criterion('Report uncertainty and overfitting risk.', /(?:interval|uncertain)[\s\S]*overfit|overfit[\s\S]*(?:interval|uncertain)/i)], 'Start with a seasonal baseline and compare it with a simple trend model. Use forward holdout or rolling backtests instead of random splits that leak future information. One year provides little evidence for stable seasonality, so report prediction intervals and scenario ranges. Complex models risk overfitting; prefer a model that beats the baseline on unseen months.'],
  ['stakeholder', 'intermediate', 'Product reasoning', 'Resolve conflicting metrics', 'Sales wants more signups; support wants fewer complaints. Propose a shared objective, guardrail, and a decision process for a feature with both effects.', [criterion('Define a customer-value or durable revenue goal.', /value|retention|profit|durable/i), criterion('Use complaints as a guardrail.', /complaint[\s\S]*(?:guardrail|threshold)|(?:guardrail|threshold)[\s\S]*complaint/i), criterion('Test and involve both stakeholders.', /(?:test|pilot)[\s\S]*(?:sales|support)|(?:sales|support)[\s\S]*(?:test|pilot)/i)], 'Agree on durable customer value, measured by retained paying users rather than signups alone. Set a complaint-rate threshold as a guardrail. Pilot the feature with a control, review retained revenue and support load, and include sales and support in the decision. Ship only if the shared objective improves without breaching the complaint threshold.'],
  ['causality', 'advanced', 'Causal reasoning', 'Revenue rose after launch', 'Revenue rose 12% after a campaign. Explain why this may not be causal, design stronger evidence, and state what would change your recommendation.', [criterion('Identify confounding such as seasonality or selection.', /confound|seasonal|selection/i), criterion('Propose randomization or a defensible comparison.', /random|difference.in.differences|control/i), criterion('Use effect uncertainty in recommendation.', /confidence|uncertain|interval/i)], 'The 12% increase may reflect seasonality, customer selection or another campaign. A randomized holdout gives stronger causal evidence; if unavailable, use a comparable control with pre-period trends and explicit assumptions. Estimate incremental profit with a confidence interval. I would change my recommendation if the interval includes a material loss or retention deteriorates.'],
  ['unit-economics', 'advanced', 'Unit economics', 'Growth with negative economics', 'A product spends $90 acquiring a customer and earns $12 monthly contribution. Average paid lifetime is six months. Analyze payback and lifetime contribution, then recommend a bounded experiment.', [criterion('Calculate $72 lifetime contribution.', /72/), criterion('Calculate 7.5 months payback or unprofitable acquisition.', /7\.5|unprofit|negative/i), criterion('Use a bounded experiment with retention or cost.', /(?:experiment|pilot|test)[\s\S]*(?:retention|cost|acquisition)|(?:retention|cost|acquisition)[\s\S]*(?:experiment|pilot|test)/i)], 'Six months times $12 gives $72 lifetime contribution, below the $90 acquisition cost. Payback takes 7.5 months, longer than expected lifetime. Scaling this channel destroys contribution before fixed costs. Run a bounded experiment to reduce acquisition cost or improve retention, with a spend cap and a success threshold above acquisition cost.'],
  ['missing-data', 'advanced', 'Data quality', 'Missing survey responses', 'Only 20% of users answer a satisfaction survey. Explain selection bias, one analysis to diagnose it, and a responsible statement of the result.', [criterion('Identify nonresponse or selection bias.', /nonresponse|selection.bias/i), criterion('Compare respondents and nonrespondents.', /(?:respond|nonrespond)[\s\S]*(?:compare|segment)|(?:compare|segment)[\s\S]*(?:respond|nonrespond)/i), criterion('Limit generalization and explain uncertainty.', /(?:not|cannot|limit)[\s\S]*(?:all|generaliz)|(?:all|generaliz)[\s\S]*(?:not|cannot|limit)/i)], 'Selection bias can affect satisfaction because highly engaged or unhappy users may answer more often. Compare respondents and nonrespondents by tenure, channel and usage, then consider weighting with stated assumptions. Report satisfaction among respondents and the 20% response rate. We cannot generalize confidently to all users without evidence that missing responses are comparable.'],
  ['launch', 'advanced', 'Risk management', 'Launch with uncertainty', 'A feature improves conversion but may increase refunds after 30 days. Design a staged rollout, delayed metric review, and rollback criteria.', [criterion('Roll out gradually with a holdout.', /(?:staged|gradual|percent|pilot)[\s\S]*(?:holdout|control)|(?:holdout|control)[\s\S]*(?:staged|gradual|percent|pilot)/i), criterion('Wait for refunds to mature.', /30|mature|delayed/i), criterion('Predefine rollback thresholds.', /rollback[\s\S]*threshold|threshold[\s\S]*rollback/i)], 'Use a staged rollout with a persistent holdout and limited exposure. Keep cohorts observable until the 30-day refund window matures, rather than declaring success from immediate conversion. Define a rollback threshold for refund rate and net contribution before launch. Review both leading and delayed metrics, and expand only when the risk-adjusted result stays positive.'],
  ['strategy', 'expert', 'Strategy', 'A defensible expansion decision', 'Design a go/no-go decision for expansion into a new market with uncertain demand. Address scenario economics, information value, capital constraints and a reversible pilot.', [criterion('Use scenarios and unit economics.', /scenario[\s\S]*(?:econom|margin)|(?:econom|margin)[\s\S]*scenario/i), criterion('Value information and bound capital risk.', /(?:information|learn)[\s\S]*(?:capital|budget)|(?:capital|budget)[\s\S]*(?:information|learn)/i), criterion('Define a reversible pilot and stop rules.', /pilot[\s\S]*(?:stop|revers)|(?:stop|revers)[\s\S]*pilot/i)], 'Build downside, base and upside scenarios using demand, contribution margin and operating cost. Compare the information gained from a small pilot with its cost under capital constraints. Set a capped budget, reversible operations and explicit stop rules for demand and margin. Commit larger capital only when observed unit economics support the base case and downside risk fits available reserves.'],
  ['allocation', 'expert', 'Portfolio decisions', 'Allocate scarce budget', 'Three teams claim the same budget. Explain a portfolio allocation method including comparable outcomes, uncertainty, dependencies, opportunity cost and review cadence.', [criterion('Compare outcomes and opportunity cost.', /opportunity.cost|comparab/i), criterion('Account for uncertainty and dependencies.', /uncertain[\s\S]*depend|depend[\s\S]*uncertain/i), criterion('Use a review cadence and reallocation.', /(?:review|cadence)[\s\S]*(?:reallocat|adjust)|(?:reallocat|adjust)[\s\S]*(?:review|cadence)/i)], 'Translate proposals into comparable incremental outcomes and opportunity cost. Use ranges for uncertainty, map dependencies, and reserve capacity for shared prerequisites. Fund a portfolio that fits risk tolerance and strategic goals instead of ranking optimistic point estimates. Review at a fixed monthly cadence with leading evidence and reallocate when assumptions fail, while protecting committed obligations.'],
  ['pricing', 'expert', 'Pricing strategy', 'Price across customer segments', 'Design segment-specific pricing without confusing customers or creating harmful incentives. Include willingness-to-pay evidence, fairness, leakage, experimentation and long-term metrics.', [criterion('Research willingness to pay.', /willingness.to.pay|customer.research/i), criterion('Address fairness and leakage.', /fair[\s\S]*leak|leak[\s\S]*fair/i), criterion('Test retention or long-term value.', /(?:experiment|test)[\s\S]*(?:retention|long.term)|(?:retention|long.term)[\s\S]*(?:experiment|test)/i)], 'Use customer research and willingness-to-pay evidence to define transparent value-based tiers. Audit fairness and whether customers can leak between segments in ways that punish honest buyers. Test pricing with clear eligibility and a holdout. Track retention, net contribution, support complaints and long-term value, and roll back segments whose apparent revenue gain hides harmful churn.'],
  ['evaluation', 'expert', 'Causal inference', 'Evaluate a nonrandom rollout', 'A policy rolls out to selected regions first. Propose a causal evaluation, its assumptions, pretrend checks, spillover risks and how uncertainty affects the conclusion.', [criterion('Use difference-in-differences or a suitable control.', /difference.in.differences|synthetic.control/i), criterion('Check parallel pretrends and spillover.', /(?:parallel|pretrend)[\s\S]*spillover|spillover[\s\S]*(?:parallel|pretrend)/i), criterion('Report uncertainty and sensitivity.', /uncertain[\s\S]*sensitiv|sensitiv[\s\S]*uncertain/i)], 'Compare treated regions with suitable controls using difference-in-differences. Check parallel pretrends, composition changes and concurrent policy changes. Spillovers into control regions can invalidate the comparison. Report uncertainty intervals and sensitivity to control selection and timing; if assumptions fail, present an association and recommend better prospective evidence rather than a causal claim.'],
];

const humanities: Scenario[] = [
  ['source', 'beginner', 'Evidence', 'Check a source', 'An unsigned social post makes a historical claim. Explain how you would verify it, distinguish primary and secondary evidence, and communicate uncertainty.', [criterion('Check authorship, date and provenance.', /author|provenance/i), criterion('Compare primary and secondary sources.', /primary[\s\S]*secondary|secondary[\s\S]*primary/i), criterion('State uncertainty rather than repeating unsupported claims.', /uncertain|unverified|cannot.confirm/i)], 'I would trace the post to its author, publication date and original source. A primary source such as a contemporaneous document supplies direct evidence, while a secondary scholarly analysis helps interpret context. Compare independent records and check whether the quotation is complete. If evidence is missing, state that the claim is unverified and explain the uncertainty.'],
  ['argument', 'beginner', 'Critical thinking', 'Separate claim from evidence', 'A proposal says attendance increased, therefore a workshop caused better learning. Identify the claim, evidence gap, and a better measurement.', [criterion('Separate attendance from learning.', /attendance[\s\S]*learning|learning[\s\S]*attendance/i), criterion('Explain why causation is unsupported.', /caus|confound/i), criterion('Use assessment or a comparison.', /assessment|pre.and.post|control|comparison/i)], 'Attendance measures participation, not learning. The causal claim is unsupported because motivated students or other changes may explain the result. Use a relevant pre-and-post assessment and a comparable group, with consent and consistent measurement. Report attendance separately from learning outcomes and acknowledge confounding if the design cannot isolate the workshop effect.'],
  ['audience', 'beginner', 'Communication', 'Explain for two audiences', 'Explain how you would present the same research finding to specialists and first-year students while keeping accuracy and one important caveat.', [criterion('Adapt language to audience.', /audience|specialist|student/i), criterion('Preserve evidence and accuracy.', /evidence|accurac/i), criterion('State a caveat or limitation.', /caveat|limit|uncertain/i)], 'For specialists I would include methods, evidence and disciplinary terms. For first-year students I would define those terms and use a concrete example suited to the audience. Both versions retain the finding and its uncertainty. The important caveat is whether the sample supports wider generalization; simplifying language must not erase that limitation or overstate accuracy.'],
  ['interview', 'beginner', 'Research methods', 'Ask without leading', 'Design three principles for interviewing someone about a community issue. Explain open questions, informed consent, and how to avoid leading or judging answers.', [criterion('Use open-ended neutral questions.', /open.ended|neutral/i), criterion('Obtain informed consent.', /consent/i), criterion('Avoid leading and use follow-up clarification.', /(?:leading|judg)[\s\S]*(?:follow|clarif)|(?:follow|clarif)[\s\S]*(?:leading|judg)/i)], 'Use open-ended neutral questions such as asking what happened before suggesting causes. Explain the purpose, recording and withdrawal rights and obtain informed consent. Avoid leading language or judging answers. Follow up with clarification, reflect the person\'s wording, and confirm interpretation before using the account as evidence.'],
  ['sampling', 'intermediate', 'Research methods', 'Choose a defensible sample', 'Plan a study of commuter-student experiences. Explain who might be missed, purposeful sampling, saturation, and a limit on generalization.', [criterion('Identify missing groups or selection.', /miss|selection|underrepresent/i), criterion('Use purposeful sampling and saturation.', /purposeful[\s\S]*saturation|saturation[\s\S]*purposeful/i), criterion('Limit generalization.', /generaliz|representative/i)], 'Recruit across travel distance, work schedules and caregiving needs so evening commuters are not missed. Purposeful sampling seeks varied experiences rather than a convenience sample. Continue until thematic saturation is plausible and document exceptions. The findings explain experiences in the sampled contexts; they are not automatically representative of every commuter or suitable for numerical generalization.'],
  ['ethics', 'intermediate', 'Ethics', 'Protect a vulnerable participant', 'A participant reveals sensitive information during research. Explain confidentiality, consent boundaries, safe handling and when institutional guidance is needed.', [criterion('Respect consent and confidentiality.', /consent[\s\S]*confidential|confidential[\s\S]*consent/i), criterion('Minimize and secure sensitive records.', /minimiz|encrypt|secure/i), criterion('Seek supervisor or ethics guidance.', /supervisor|ethics|institutional/i)], 'Pause to confirm consent boundaries and explain any confidentiality limits established before participation. Minimize sensitive records, pseudonymize them and store them securely with restricted access. Do not promise protections the study cannot provide. Consult the supervisor or institutional ethics process about required reporting or additional safeguards, then document the decision without unnecessary identifying details.'],
  ['synthesis', 'intermediate', 'Evidence', 'Synthesize conflicting accounts', 'Two credible sources disagree about an event. Explain how you would compare context, methods, incentives and corroboration before writing a synthesis.', [criterion('Compare context and methods.', /context[\s\S]*method|method[\s\S]*context/i), criterion('Look for independent corroboration.', /corroborat|independent/i), criterion('Represent disagreement and uncertainty.', /disagree|uncertain/i)], 'Compare each source\'s context, methods, access to the event and incentives. Seek independent corroboration rather than counting repeated versions of one source. Identify what both accounts support and where they disagree. A synthesis should preserve uncertainty, explain the stronger evidence for particular details, and distinguish interpretation from established facts instead of forcing a false consensus.'],
  ['policy', 'intermediate', 'Policy reasoning', 'Compare two policies', 'Compare a universal program with a targeted program. Address access, administrative burden, distributional effects and one measure of success.', [criterion('Discuss access and administrative burden.', /access[\s\S]*burden|burden[\s\S]*access/i), criterion('Compare distribution or equity.', /distribution|equity|fair/i), criterion('Define an outcome metric.', /measure|metric|outcome/i)], 'A universal program can improve access and reduce eligibility burden but spends resources on people with less need. A targeted program concentrates benefits but adds administrative burden and may exclude eligible participants. Compare distributional effects and equity using actual uptake by group. Measure an outcome tied to the program goal, alongside application completion and exclusion rates.'],
  ['analysis', 'advanced', 'Qualitative analysis', 'Code an interview corpus', 'Design a thematic analysis of 40 interviews. Describe a codebook, reflexivity, contradictory cases, inter-coder discussion and an audit trail.', [criterion('Create and revise a codebook.', /codebook/i), criterion('Address reflexivity and contradictory cases.', /reflexiv[\s\S]*(?:contradict|negative.case)|(?:contradict|negative.case)[\s\S]*reflexiv/i), criterion('Keep an audit trail and discuss coding differences.', /audit[\s\S]*(?:coder|coding)|(?:coder|coding)[\s\S]*audit/i)], 'Start with a provisional codebook, test it on varied interviews and revise definitions with examples. Record reflexivity notes about researcher assumptions and actively inspect contradictory cases. Discuss inter-coder differences to clarify interpretations rather than manufacture agreement. Keep an audit trail of codebook changes, analytic decisions and evidence supporting each theme, while protecting participant identities.'],
  ['impact', 'advanced', 'Evaluation', 'Evaluate a community program', 'Plan a mixed-method evaluation of a community program. Include theory of change, comparison, participant voice, unintended effects and a limit on causal claims.', [criterion('State a theory of change.', /theory.of.change/i), criterion('Combine comparison and participant evidence.', /compar[\s\S]*(?:participant|interview)|(?:participant|interview)[\s\S]*compar/i), criterion('Address unintended effects and causality.', /unintended[\s\S]*caus|caus[\s\S]*unintended/i)], 'Define a theory of change connecting activities to outcomes. Combine a defensible comparison of outcome trends with participant interviews that explain mechanisms and barriers. Include people who left the program and examine unintended effects. Without randomization, confounding may remain; limit causal claims, state assumptions and use mixed evidence to guide improvements rather than declare proven impact.'],
  ['archive', 'advanced', 'Historical methods', 'Read an incomplete archive', 'An archive excludes some groups. Explain provenance, archival silence, triangulation and how you would avoid treating absence as proof.', [criterion('Assess provenance and archival silence.', /provenance[\s\S]*silence|silence[\s\S]*provenance/i), criterion('Triangulate with other records or oral history.', /triangulat|oral.history/i), criterion('Avoid absence-as-proof claims.', /absence[\s\S]*(?:not|avoid|proof)|(?:not|avoid|proof)[\s\S]*absence/i)], 'Assess provenance: who created and preserved records, for what purpose, and whose voices were excluded. Archival silence may reflect unequal access rather than absence of an event. Triangulate with oral history, material evidence and other collections while evaluating their limitations. Do not treat absence as proof; describe what the archive can establish and where uncertainty remains.'],
  ['public-writing', 'advanced', 'Communication', 'Write an honest public brief', 'Design a one-page brief on disputed research. Explain the central claim, evidence strength, competing interpretations, accessibility and correction process.', [criterion('Match claim strength to evidence.', /claim[\s\S]*evidence|evidence[\s\S]*claim/i), criterion('Represent competing interpretations.', /competing|alternative|disagree/i), criterion('Plan accessible communication and corrections.', /accessib[\s\S]*correct|correct[\s\S]*accessib/i)], 'Lead with a claim proportionate to evidence, followed by methods and the main uncertainty in accessible language. Represent competing interpretations fairly and identify what evidence would distinguish them. Use readable typography and explain technical terms. Publish sources and a visible correction process so new evidence or mistakes can be addressed without hiding earlier limitations.'],
  ['design', 'expert', 'Research design', 'A participatory study', 'Design a participatory study where community members share decision power. Address governance, compensation, evidence standards, conflict and ownership of findings.', [criterion('Share governance and compensate participants.', /governance[\s\S]*compensat|compensat[\s\S]*governance/i), criterion('Define evidence standards and conflict process.', /evidence[\s\S]*conflict|conflict[\s\S]*evidence/i), criterion('Agree on ownership and publication.', /ownership[\s\S]*(?:publish|publication)|(?:publish|publication)[\s\S]*ownership/i)], 'Create joint governance with explicit decision rights and compensate community partners for their work. Agree on evidence standards, consent and a conflict-resolution process before collecting data. Establish ownership of records and findings, publication review and limits on withdrawal of already aggregated evidence. Document decisions transparently and keep room for dissent so participation changes power rather than serving as endorsement.'],
  ['inference', 'expert', 'Inference', 'Defend an interpretive claim', 'A committee challenges your interpretation. Explain an inference chain, rival explanations, disconfirming evidence, positionality and the limits of your conclusion.', [criterion('Connect evidence to inference.', /inference[\s\S]*evidence|evidence[\s\S]*inference/i), criterion('Test rival explanations and disconfirmation.', /rival[\s\S]*disconfirm|disconfirm[\s\S]*rival/i), criterion('Discuss positionality and limits.', /positionality[\s\S]*limit|limit[\s\S]*positionality/i)], 'Make the inference chain explicit from source evidence to interpretation, including assumptions. Compare rival explanations and identify disconfirming evidence that would weaken the claim. Explain my positionality and how it influences source selection and reading. Defend the conclusion only within the limits the evidence supports, and revise it when a stronger rival account explains the observations.'],
  ['justice', 'expert', 'Policy evaluation', 'Evaluate unequal effects', 'A policy improves an average outcome but harms a smaller group. Design an evaluation and recommendation covering distribution, stakeholder power, uncertainty and alternatives.', [criterion('Disaggregate outcomes and distribution.', /disaggregat|distribution/i), criterion('Include stakeholder power and uncertainty.', /power[\s\S]*uncertain|uncertain[\s\S]*power/i), criterion('Compare alternatives and mitigation.', /alternative[\s\S]*mitigat|mitigat[\s\S]*alternative/i)], 'Disaggregate outcomes by relevant groups and inspect distribution rather than relying on the average. Include affected stakeholders while accounting for unequal power in consultations. Quantify uncertainty and investigate mechanisms of harm. Compare alternatives and mitigation, including whether the goal can be reached without that harm. Recommend a bounded policy change with monitoring and explicit thresholds for reconsideration.'],
  ['translation', 'expert', 'Knowledge translation', 'Translate without flattening', 'Translate contested academic findings into a practical recommendation. Address evidence quality, context transfer, tradeoffs, dissent and how new evidence changes advice.', [criterion('Assess evidence quality and context transfer.', /evidence[\s\S]*context|context[\s\S]*evidence/i), criterion('State tradeoffs and dissent.', /tradeoff[\s\S]*dissent|dissent[\s\S]*tradeoff/i), criterion('Define revision triggers.', /new.evidence|revision|reconsider/i)], 'Assess evidence quality and whether the original context transfers to the decision setting. State tradeoffs, assumptions and dissent alongside the recommendation so practical advice does not flatten contested findings. Specify a feasible action and monitoring measures. Define revision triggers, including new evidence that undermines the mechanism or observed harms that outweigh benefits, and keep the advice open to reconsideration.'],
];

const health: Scenario[] = [
  ['study-risk', 'beginner', 'Study interpretation', 'Interpret a study result', 'A study reports risk falls from 10% to 8%. Calculate absolute and relative reduction and explain why the study alone does not determine care for an individual. This is an interview exercise, not clinical advice.', [criterion('Calculate 2 percentage points absolute reduction.', /2\s*(?:percentage|percent|%)/i), criterion('Calculate 20% relative reduction.', /20\s*%/), criterion('Consider study population and clinical context.', /population|context|clinician/i)], 'Absolute reduction is 2 percentage points, from 10% to 8%. Relative reduction is 2 divided by 10, or 20%. The study population, uncertainty, harms and individual clinical context matter. This finding alone does not establish appropriate care for a person; decisions require qualified clinical review and applicable guidance.'],
  ['privacy', 'beginner', 'Privacy', 'Keep participant data private', 'For a student research project, explain how you would collect only needed health information, obtain consent, store it safely and handle a request for access.', [criterion('Minimize data and obtain consent.', /minimiz[\s\S]*consent|consent[\s\S]*minimiz/i), criterion('Use secure storage and restricted access.', /(?:secure|encrypt)[\s\S]*access|access[\s\S]*(?:secure|encrypt)/i), criterion('Verify authorization before disclosure.', /authoriz|identity|verify/i)], 'Minimize collection to data needed for the research question and obtain informed consent for defined uses. Store records securely with encryption and restricted access, separating identifiers where possible. For an access request, verify identity and authorization and follow the approved institutional procedure. Never disclose records because a request appears informal or urgent.'],
  ['denominator', 'beginner', 'Data literacy', 'Use the right denominator', 'A survey finds 30 of 150 respondents report an issue. Calculate the proportion, explain the denominator and name one sampling limitation.', [criterion('Calculate 20%.', /20\s*%/), criterion('Use 150 respondents as denominator.', /150[\s\S]*respond|respond[\s\S]*150/i), criterion('Discuss sampling or nonresponse limitation.', /sampl|nonresponse|selection/i)], 'The proportion is 30 divided by 150, or 20%. The denominator is the 150 respondents, not everyone invited to the survey. If nonrespondents differ from respondents, selection bias limits generalization. Report the response rate and sampling method before treating this as an estimate for the broader population.'],
  ['handoff', 'beginner', 'Communication', 'Give a clear handoff', 'Explain a structured handoff in a supervised training setting. Include situation, relevant background, uncertainty and escalation to the qualified supervisor.', [criterion('Summarize situation and relevant background.', /situation[\s\S]*background|background[\s\S]*situation/i), criterion('State uncertainty and check understanding.', /uncertain[\s\S]*(?:confirm|understand)|(?:confirm|understand)[\s\S]*uncertain/i), criterion('Escalate within supervision boundaries.', /supervisor|qualified|escalat/i)], 'State the situation, then concise relevant background and observed facts. Distinguish confirmed information from uncertainty and avoid unsupported diagnoses. Explain the next supervised task and any escalation concern to the qualified supervisor. Ask the receiver to confirm understanding and clarify ownership so the handoff does not leave an important action ambiguous.'],
  ['bias', 'intermediate', 'Epidemiology', 'Selection changes a study', 'A study recruits only volunteers from one clinic. Explain selection bias, external validity and a better recruitment or analysis strategy.', [criterion('Explain selection bias.', /selection.bias/i), criterion('Limit generalization beyond the clinic.', /generaliz|external.validity/i), criterion('Improve recruitment or compare samples.', /(?:recruit|sampl)[\s\S]*(?:multiple|compare|diverse)|(?:multiple|compare|diverse)[\s\S]*(?:recruit|sampl)/i)], 'Volunteers at one clinic may differ in health, access and motivation, creating selection bias. External validity is limited; the results may not generalize beyond that population. Recruit across multiple settings with transparent eligibility or compare the sample with the target population. Weighting can help only under justified assumptions and does not automatically remove unmeasured selection.'],
  ['diagnostic', 'intermediate', 'Statistics', 'Interpret a screening test', 'Explain why a positive screening result depends on prevalence as well as sensitivity and specificity. Describe false positives and the need for qualified follow-up, without giving clinical advice.', [criterion('Explain prevalence affects positive predictive value.', /prevalence[\s\S]*(?:predictive|positive)|(?:predictive|positive)[\s\S]*prevalence/i), criterion('Discuss sensitivity, specificity and false positives.', /sensitiv[\s\S]*specific|specific[\s\S]*sensitiv/i), criterion('Require qualified follow-up.', /qualified|clinician|follow.up/i)], 'Positive predictive value depends on prevalence: when a condition is uncommon, false positives can outnumber true positives even with good sensitivity and specificity. Sensitivity describes detection among affected people; specificity describes negatives among unaffected people. A screening result requires qualified follow-up within appropriate guidance and clinical context, rather than being treated as a diagnosis.'],
  ['improvement', 'intermediate', 'Quality improvement', 'Measure a workflow change', 'Design a supervised quality-improvement pilot to reduce appointment delays. Define a process measure, outcome measure, balancing measure and review cycle.', [criterion('Measure delay and a process step.', /delay|wait|time.to.appointment/i), criterion('Use a balancing measure such as workload.', /balanc|workload|safety/i), criterion('Pilot and review in cycles.', /pilot[\s\S]*(?:cycle|review)|(?:cycle|review)[\s\S]*pilot/i)], 'Pilot a small scheduling change under supervision. Measure time to appointment as the outcome and completion of the scheduling step as a process measure. Use staff workload and missed appointments as balancing measures so faster service does not hide harm. Review weekly cycles against baseline, learn from exceptions and expand only after the supervised team agrees the evidence supports improvement.'],
  ['consent', 'intermediate', 'Research ethics', 'Consent that people understand', 'Plan informed consent for a research study. Address comprehension, voluntariness, withdrawal, privacy limits and institutional review.', [criterion('Check comprehension and voluntariness.', /comprehension[\s\S]*voluntar|voluntar[\s\S]*comprehension/i), criterion('Explain withdrawal and privacy limits.', /withdraw[\s\S]*privacy|privacy[\s\S]*withdraw/i), criterion('Use institutional ethics review.', /institutional|ethics.review/i)], 'Use plain language and a comprehension check, and make participation voluntary without pressure from a care relationship. Explain withdrawal options, data uses and privacy limits, including limits after data are aggregated. Follow institutional ethics review and the approved consent process. Give time for questions and document consent without treating a signature alone as proof of understanding.'],
  ['confounding', 'advanced', 'Study design', 'A treatment association', 'An observational study finds an intervention is associated with better outcomes. Explain confounding by indication, adjustment limits and a stronger design.', [criterion('Explain confounding by indication.', /confounding[\s\S]*indication|indication[\s\S]*confounding/i), criterion('Address unmeasured confounding.', /unmeasured/i), criterion('Propose randomization or a defensible comparison.', /random|target.trial|control/i)], 'Confounding by indication occurs when the reason people receive an intervention also predicts outcomes. Adjusting measured baseline factors helps but cannot eliminate unmeasured confounding or poor overlap. A randomized study, where ethical and feasible, provides stronger evidence. A carefully specified target-trial emulation can clarify observational assumptions, but the association should not be presented as proven treatment effect.'],
  ['missing', 'advanced', 'Data quality', 'Missing follow-up data', 'Follow-up is missing for 35% of a study sample. Explain mechanisms of missingness, sensitivity analysis and a transparent report.', [criterion('Discuss missingness mechanisms.', /missing.at.random|not.at.random|mechanism/i), criterion('Use sensitivity analysis.', /sensitivity/i), criterion('Report 35% missing and limits.', /35[\s\S]*(?:limit|report)|(?:limit|report)[\s\S]*35/i)], 'Investigate whether follow-up is missing at random given observed factors or not at random because outcomes affect participation. Compare baseline characteristics and document reasons. Use justified imputation plus sensitivity analyses under different missingness assumptions. Report that 35% are missing, how analysis handles them and how conclusions change; avoid hiding that limitation behind a single estimate.'],
  ['equity', 'advanced', 'Public health', 'An uneven program effect', 'A health program improves averages but access worsens for one group. Design an equity analysis with denominators, stakeholder input and a correction plan.', [criterion('Disaggregate and use comparable denominators.', /disaggregat[\s\S]*denominator|denominator[\s\S]*disaggregat/i), criterion('Include affected stakeholders.', /stakeholder|affected/i), criterion('Monitor a correction with access metrics.', /(?:correct|change)[\s\S]*(?:access|monitor)|(?:access|monitor)[\s\S]*(?:correct|change)/i)], 'Disaggregate access and outcomes by relevant groups using comparable denominators and time windows. Examine whether eligibility or measurement hides excluded people. Include affected stakeholders in interpreting barriers. Develop a correction plan with supervised owners and monitor access metrics, workload and unintended effects. Average improvement cannot substitute for an explanation of unequal harm.'],
  ['measurement', 'advanced', 'Measurement', 'Check a new outcome scale', 'Assess a new survey outcome scale. Explain reliability, validity, cultural context, responsiveness and the risk of using it before validation.', [criterion('Distinguish reliability and validity.', /reliab[\s\S]*valid|valid[\s\S]*reliab/i), criterion('Assess cultural context and responsiveness.', /cultur[\s\S]*responsiv|responsiv[\s\S]*cultur/i), criterion('State validation limits.', /validat[\s\S]*(?:before|risk|limit)|(?:before|risk|limit)[\s\S]*validat/i)], 'Reliability concerns consistency; validity concerns whether the scale measures the intended construct. Assess content and construct validity with the target population, including cultural context and language. Check responsiveness to meaningful change without confusing random fluctuation with improvement. Using the scale before validation risks misleading comparisons, so report limits and compare with established measures in a supervised validation study.'],
  ['causal', 'expert', 'Causal inference', 'Define a target trial', 'Outline a target-trial emulation using observational data. Include eligibility, time zero, strategies, outcomes, confounding, immortal-time bias and sensitivity.', [criterion('Align eligibility, time zero and strategies.', /eligib[\s\S]*time.zero|time.zero[\s\S]*eligib/i), criterion('Address confounding and immortal-time bias.', /confound[\s\S]*immortal|immortal[\s\S]*confound/i), criterion('Use sensitivity and limits on causal conclusions.', /sensitiv[\s\S]*(?:caus|limit)|(?:caus|limit)[\s\S]*sensitiv/i)], 'Specify eligibility, treatment strategies, assignment, follow-up, outcomes and analysis as if designing the target trial. Align time zero with eligibility and strategy assignment to avoid immortal-time bias. Adjust measured confounding with justified methods and assess overlap. Perform sensitivity analyses for unmeasured confounding and outcome definitions. Causal conclusions remain limited by observational assumptions and data quality.'],
  ['implementation', 'expert', 'Implementation science', 'Scale a supported intervention', 'Plan scaling an evidence-supported program across sites. Address fidelity versus adaptation, context, implementation outcomes, equity and governance.', [criterion('Balance fidelity and adaptation.', /fidelity[\s\S]*adapt|adapt[\s\S]*fidelity/i), criterion('Measure implementation and context.', /context[\s\S]*(?:adoption|implementation)|(?:adoption|implementation)[\s\S]*context/i), criterion('Define equity and governance review.', /equity[\s\S]*governance|governance[\s\S]*equity/i)], 'Identify core components that require fidelity and adaptations that fit local context. Measure adoption, feasibility, reach and sustainability as implementation outcomes alongside program effects. Include equity in reach and burden, not only average success. Establish cross-site governance with local participation, staged expansion and review triggers, documenting adaptations so results remain interpretable and unsafe drift is addressed.'],
  ['risk-model', 'expert', 'Model evaluation', 'Evaluate a risk model fairly', 'Evaluate a prediction model before institutional use. Cover calibration, discrimination, subgroup performance, leakage, prospective validation and human oversight.', [criterion('Measure calibration and discrimination.', /calibration[\s\S]*discrimination|discrimination[\s\S]*calibration/i), criterion('Check subgroup performance and leakage.', /subgroup[\s\S]*leakage|leakage[\s\S]*subgroup/i), criterion('Require prospective validation and oversight.', /prospective[\s\S]*oversight|oversight[\s\S]*prospective/i)], 'Measure calibration and discrimination on held-out data with uncertainty, then inspect subgroup performance and missing-data patterns. Audit leakage from future information or duplicated people across splits. Conduct prospective validation in the intended workflow and define human oversight and escalation. A high overall score does not establish benefit or fairness; monitor drift, burden and unintended effects before expanding institutional use.'],
  ['evidence', 'expert', 'Evidence synthesis', 'Synthesize heterogeneous studies', 'Plan a review of studies with different populations and outcome definitions. Discuss protocol, risk of bias, heterogeneity, pooling decisions and certainty of evidence.', [criterion('Predefine a protocol and assess risk of bias.', /protocol[\s\S]*bias|bias[\s\S]*protocol/i), criterion('Assess heterogeneity before pooling.', /heterogeneity[\s\S]*pool|pool[\s\S]*heterogeneity/i), criterion('Report certainty and limitations.', /certainty[\s\S]*limit|limit[\s\S]*certainty/i)], 'Predefine a protocol with inclusion criteria, outcomes and search strategy, then assess risk of bias for each study. Compare populations and outcome definitions to judge heterogeneity before pooling. A narrative synthesis may be more defensible when effects are not comparable. Report certainty of evidence, uncertainty and limitations, including publication bias, without turning a pooled estimate into individual clinical advice.'],
];

for (const [track, entries] of [['business', business], ['humanities', humanities], ['health', health]] as [Track, Scenario[]][]) {
  for (const [id, level, topic, title, prompt, criteria, example] of entries) technical(track, `${track}-${id}`, level, topic, title, prompt, criteria, example);
}

const behavioral: [string, string, string, RegExp][] = [
  ['teamwork', 'Make the team better', 'Tell me about a project where your team depended on you. Explain the situation, your responsibility, one specific action, the result and what you learned.', /team|teammate|colleague|group/i],
  ['conflict', 'Handle disagreement', 'Describe a disagreement in a project or workplace. Explain how you listened, what you personally did, the outcome and what you would change.', /listen|perspective|disagree|conflict/i],
  ['failure', 'Learn from a setback', 'Tell me about a mistake or setback. Own your part, explain your corrective action, give evidence of the result and explain your learning.', /mistake|setback|fail|correct/i],
  ['ambiguity', 'Work without a clear brief', 'Describe an ambiguous task. Explain how you clarified the goal, acted under uncertainty, checked the result and learned from it.', /clarif|ambig|uncertain|goal/i],
  ['leadership', 'Lead without a title', 'Tell me about influencing others without formal authority. Give a concrete situation, your action, evidence of impact and a lesson.', /influenc|lead|persuad|align/i],
  ['feedback', 'Use difficult feedback', 'Describe feedback that was hard to hear. Explain how you understood it, changed your work, measured the effect and reflected.', /feedback|criticism|review/i],
  ['deadline', 'Deliver under pressure', 'Tell me about competing deadlines. Explain how you prioritized, communicated a tradeoff, delivered a result and learned.', /deadline|priorit|tradeoff|pressure/i],
  ['motivation', 'Explain your direction', 'Describe a project that shaped your career interest. Explain your contribution, its impact, what you learned and why it connects to this role.', /career|interest|role|motiv/i],
];
const behaviorExamples: Record<string, string> = {
  teamwork: 'During a class project, our team was behind because tasks overlapped. I asked each teammate about their responsibilities, proposed a shared checklist and wrote integration tests for my part. I reviewed progress daily and helped resolve a blocked handoff. The result was a completed demo on time with fewer errors. I learned to confirm ownership before starting and to ask for help earlier when a dependency is unclear.',
  conflict: 'In a group project, two teammates disagreed about how much detail to include in our presentation. I listened to both perspectives and asked what each wanted the audience to understand. I proposed a short main presentation with an optional appendix, then tested it with a classmate. The result was a clearer presentation that the team supported. I learned that a shared goal can make disagreement useful, and next time I would discuss audience needs sooner.',
  failure: 'In a class project, I made a mistake by assuming the input format would never change. The first demo failed when a teammate supplied a different format. I corrected the parser, added boundary tests and asked the team to review the interface contract. The result was a completed demo that handled both formats. I learned to validate assumptions with examples before coding, and next time I would test the handoff earlier.',
  ambiguity: 'At a student volunteering project, the task was to improve our signup process, but the goal was ambiguous. I asked the organizer to clarify success and reviewed where people stopped completing the form. I proposed a smaller form, tested it with volunteers and documented open questions. The result was a completed revision with fewer confusing steps. I learned to turn uncertainty into a testable goal before committing to a large change.',
  leadership: 'During a class project, I wanted to influence the team to add testing even though I had no formal authority. I proposed one small test for a repeated failure and showed how it saved review time. I asked teammates to choose checks for their parts and created a shared test checklist. The result was a completed project with a smoother demo. I learned to lead through useful evidence and shared ownership rather than insisting on my preference.',
  feedback: 'After a practice presentation, I received feedback that my explanation was difficult to follow. I asked which section caused confusion and listened without defending the draft. I rewrote the opening around one example and reviewed it with a classmate before the next presentation. The result was an improved explanation that the audience could summarize correctly. I learned to check understanding early, and next time I would ask for feedback before polishing the slides.',
  deadline: 'I had two class projects with the same deadline and could not complete every optional feature. I prioritized required outcomes, asked both teammates about dependencies and proposed a clear tradeoff: finish the working core before extras. I scheduled check-ins and wrote a short progress summary each day. The result was two completed submissions on time. I learned to communicate scope changes early and to protect time for final review under pressure.',
  motivation: 'A community research project shaped my career interest because I enjoyed turning an unclear question into useful evidence. I asked participants about their needs, organized the responses and wrote a summary for the project lead. The result was a completed recommendation that guided the next event. I learned that careful listening and analysis can improve practical decisions. This motivates me to seek a role where I can develop those skills and contribute to meaningful projects.',
};
for (const [id, title, prompt, topicPattern] of behavioral) {
  specs.push({ track: 'all', question: { id: `behavior-${id}`, kind: 'behavioral', topic: 'Behavioral', difficulty: 'intermediate', title, prompt, hints: ['Describe a real situation and your responsibility.', 'Explain a specific action you personally took.', 'Give the result and what you learned.'] }, criteria: [criterion('Give concrete context and your personal action.', /\bI\b[\s\S]*(?:built|created|organized|wrote|asked|tested|changed|scheduled|met|proposed|led|reviewed|implemented|prioritized|listened|clarified)/i), criterion('Show an outcome and reflection.', /(?:result|improved|reduced|increased|delivered|completed|resolved|shipped|finished|launched|adopted|on.time|fewer)[\s\S]*(?:learned|next.time|reflect)|(?:learned|next.time|reflect)[\s\S]*(?:result|improved|reduced|increased|delivered|completed|resolved|shipped|finished|launched|adopted|on.time|fewer)/i), criterion('Address the specific interview topic.', topicPattern)], example: behaviorExamples[id]! });
}

export const QUESTION_SPECS: readonly QuestionSpec[] = specs;
export const QUESTIONS: readonly Question[] = specs.map(spec => spec.question);
export function specForQuestion(id: string): QuestionSpec {
  const found = specs.find(spec => spec.question.id === id);
  if (!found) throw new Error('Unknown question.');
  return found;
}

export const LESSONS: Lesson[] = [
  { id: 'beginner-reasoning', title: 'Explain your reasoning', topic: 'Technical foundations', level: 'beginner', minutes: 8, summary: 'Turn a first answer into an explanation someone can follow.', sections: [{ title: 'State the problem', body: 'Restate the goal in your own words. Identify the input, expected output and one constraint. If a term is ambiguous, ask what it means before solving. In any major, a clear problem statement prevents a polished answer to the wrong question.' }, { title: 'Use a small example', body: 'Work through one ordinary case and one boundary case. For code, trace a short input and an empty input. For an analysis, check units and the denominator. For a research claim, distinguish observation from interpretation. Say what your example can establish and what it cannot.' }, { title: 'Check before concluding', body: 'Compare the result with the original goal. Explain why your approach works, its cost or uncertainty, and how you would test it. A useful answer includes a reason, not just a conclusion. When unsure, name the missing information and the next check.' }], check: { prompt: 'You are unsure what an interviewer means by "fast." What is the best first step?', choices: ['Guess and start immediately.', 'Clarify the relevant constraint and expected workload.', 'Use the most complicated method.', 'Avoid discussing tradeoffs.'], correct: 1, explanation: 'Clarifying the constraint makes the problem testable and keeps the answer relevant.' } },
  { id: 'beginner-star', title: 'Tell a concrete story', topic: 'Behavioral', level: 'beginner', minutes: 7, summary: 'Use situation, task, action and result without memorizing a script.', sections: [{ title: 'Choose a real moment', body: 'Use a class project, job, volunteering or personal project. Describe the situation briefly and state your responsibility. The interviewer needs enough context to understand the difficulty, not the entire history.' }, { title: 'Make your action visible', body: 'Explain what you personally did and why. Be fair about teammates. Replace "we worked hard" with a concrete action, such as organizing a task list, testing a risk or asking for feedback. Do not invent experience or numbers.' }, { title: 'Show result and learning', body: 'Give an honest observable result. A delivered prototype or corrected misunderstanding counts when precise metrics are unavailable. Explain what you learned and what you would change. A setback story can be strong when it shows ownership and a credible improvement.' }], check: { prompt: 'Which action statement gives the clearest evidence?', choices: ['We did a lot of work.', 'I am a great communicator.', 'I scheduled a review and rewrote the unclear handoff checklist.', 'Everyone liked the project.'], correct: 2, explanation: 'A specific action shows your contribution and gives the interviewer something to examine.' } },
  { id: 'intermediate-validation', title: 'Validate an answer', topic: 'Technical reasoning', level: 'intermediate', minutes: 10, summary: 'Use examples, comparisons and uncertainty to test your own conclusion.', sections: [{ title: 'Choose a baseline', body: 'Compare your approach with something simple. In software, start with a correct straightforward method. In business, compare against current practice. In research, distinguish a claim from its supporting evidence. A baseline makes improvement meaningful.' }, { title: 'Test the boundaries', body: 'Look for empty inputs, missing information, unusual groups and changing assumptions. State what should happen in each case. Tests should challenge the claim, not repeat the implementation. Consider where selection, measurement or timing could change the result.' }, { title: 'Report limits', body: 'Explain complexity, resource cost, confidence or generalization limits as appropriate to your field. Do not claim causation from a correlation or code correctness from a few matching examples. Name a failure condition and the check that would reveal it.' }], check: { prompt: 'A result improves after a change. What most strengthens your explanation?', choices: ['Ignore other changes.', 'Declare causation immediately.', 'Compare with a baseline and test plausible alternative explanations.', 'Remove uncertainty from the report.'], correct: 2, explanation: 'A baseline and alternative explanations help distinguish a useful effect from coincidence or confounding.' } },
  { id: 'intermediate-feedback', title: 'Turn feedback into action', topic: 'Behavioral', level: 'intermediate', minutes: 8, summary: 'Respond to critique with a clear correction and evidence.', sections: [{ title: 'Understand first', body: 'Ask for the example behind the feedback. Summarize what you heard and check understanding. Listening does not require agreeing with every interpretation, but it helps separate useful observations from assumptions.' }, { title: 'Choose a correction', body: 'Select one change within your control and explain why it addresses the concern. If the issue is unclear communication, test a revised summary with the audience. If the issue is technical, add a check that catches the failure. Avoid treating intent as proof of impact.' }, { title: 'Close the loop', body: 'Review the outcome after the change. Show what improved, what remains uncertain and what you will try next. In an interview, connect the feedback to a concrete action and result. Credible reflection includes an adjustment you can describe.' }], check: { prompt: 'Which response best closes the feedback loop?', choices: ['Explain why the critic is wrong.', 'Promise to do better without a plan.', 'Hide the mistake.', 'Make a targeted change and check its effect with evidence.'], correct: 3, explanation: 'Feedback becomes learning when a targeted action produces an observable check.' } },
  { id: 'advanced-tradeoffs', title: 'Make tradeoffs explicit', topic: 'Technical judgment', level: 'advanced', minutes: 12, summary: 'Compare alternatives against constraints instead of declaring one universal answer.', sections: [{ title: 'Name the constraints', body: 'Identify correctness, cost, time, privacy and user needs. Decide which constraints are hard requirements and which can be traded. A solution that violates an essential boundary is not rescued by a good average result.' }, { title: 'Compare two options', body: 'Explain one advantage and one failure mode of each option. Use evidence from the problem instead of generic preferences. A simpler option may be easier to validate; a more capable option may require monitoring, expertise or additional data.' }, { title: 'Define reconsideration', body: 'State what would change your recommendation. This could be a workload threshold, a guardrail breach or evidence that an assumption is false. Pair your decision with a measurable check and a reversible next step where possible.' }], check: { prompt: 'What makes a tradeoff recommendation defensible?', choices: ['One option is always best.', 'It links alternatives to constraints and states a condition for reconsideration.', 'It uses the most impressive terminology.', 'It hides the disadvantages.'], correct: 1, explanation: 'A defensible recommendation explains fit and the evidence that could change it.' } },
  { id: 'advanced-conflict', title: 'Disagree constructively', topic: 'Behavioral', level: 'advanced', minutes: 9, summary: 'Resolve disagreement with shared goals and a clear decision process.', sections: [{ title: 'Find the shared goal', body: 'Ask what each person is trying to protect. A disagreement may concern different constraints rather than competence. State the common outcome and summarize both positions fairly before defending yours.' }, { title: 'Move toward evidence', body: 'Suggest a small test, comparison or decision rule. Make ownership and deadlines clear. If a decision needs escalation, explain the unresolved risk and involve the appropriate person without misrepresenting the other side.' }, { title: 'Reflect honestly', body: 'In an interview, include your action, the outcome and your part in the difficulty. A successful story does not require winning the argument. Show how the team reached a workable decision and what you would improve next time.' }], check: { prompt: 'Two teammates prefer different approaches. What is the strongest next move?', choices: ['State the shared goal, compare constraints and agree on evidence for a decision.', 'Treat disagreement as disloyalty.', 'Avoid the issue until the deadline.', 'Claim your preference has no downsides.'], correct: 0, explanation: 'Shared goals and evidence make disagreement actionable and reduce personal conflict.' } },
  { id: 'expert-systems', title: 'Reason across a system', topic: 'Mastery', level: 'expert', minutes: 14, summary: 'Trace effects, failure boundaries and evidence across a complete process.', sections: [{ title: 'Map the boundary', body: 'Name what each part owns and where authority lives. In software, identify state and transactions. In an organization, identify decision rights and handoffs. In research, trace recruitment, measurement and interpretation. A boundary is useful when it makes a responsibility testable.' }, { title: 'Challenge the happy path', body: 'Consider retries, missing data, changing context, unequal effects and partial failures. Explain what must remain true when something goes wrong. Design a check for the invariant and specify a recovery path that does not silently erase the problem.' }, { title: 'Monitor and revise', body: 'Choose measures that reveal the failure modes you named. Include subgroup or tail behavior where averages can hide harm. Define who reviews evidence and when a decision changes. Mastery combines a strong initial answer with a reliable way to learn when it fails.' }], check: { prompt: 'Which check best demonstrates system-level reasoning?', choices: ['Show only a successful demo.', 'Use average results alone.', 'Describe an invariant, test a partial failure and define recovery.', 'Assume retries never occur.'], correct: 2, explanation: 'An invariant plus a failure test exposes whether the process remains correct beyond its happy path.' } },
  { id: 'expert-mentoring', title: 'Help someone else improve', topic: 'Mastery', level: 'expert', minutes: 10, summary: 'Explain your judgment and give feedback someone can act on.', sections: [{ title: 'Diagnose the gap', body: 'Ask the learner to explain their reasoning. Identify the smallest misconception behind the result instead of overwhelming them with every possible improvement. Separate a missing concept from a careless slip or an unclear requirement.' }, { title: 'Give a useful correction', body: 'Use one concrete example and explain why the original approach failed. Suggest a check or practice task that targets the gap. Feedback should describe the work and a next step, not label the person.' }, { title: 'Check transfer', body: 'Ask for a different problem using the same idea. Correcting a copied answer is not evidence of transfer. Look for independent reasoning, a valid result and a reflection on the earlier error. Teaching is a way to test your own understanding too.' }], check: { prompt: 'How do you check that someone learned from an error?', choices: ['Ask them to repeat your exact answer.', 'Let them solve a different problem using the same principle and explain it.', 'Mark the lesson complete after reading.', 'Give only a grade.'], correct: 1, explanation: 'A different problem with an explanation checks understanding beyond memorized correction.' } },
];
